// H7 Set A, job 4: file transform -- plain Node. Generated by
// gen_jobs.py.
import fs from "node:fs";

function fmt(cents) {
  const whole = cents / 100n;
  const frac = cents % 100n;
  let s = `${whole}.${frac.toString().padStart(2, "0")}`;
  if (s.includes(".")) s = s.replace(/0+$/, "").replace(/\.$/, "");
  return s;
}

const body = fs.readFileSync("/tmp/planes_h7_bench/file_transform_input.csv", "utf-8");
const rows = body
  .replace(/\n$/, "")
  .split("\n")
  .map((line) => line.split(","));

const outLines = rows.map(([id, name, qty, price]) => {
  const priceCents = BigInt(Math.round(parseFloat(price) * 100));
  const totalCents = BigInt(qty) * priceCents; // exact: price already whole cents
  return `${id},${name.toUpperCase()},${qty},${price},${fmt(totalCents)}`;
});

const document = outLines.join("\n") + "\n";
fs.writeFileSync("/tmp/planes_h7_bench/file_transform_output_mjs.csv", document);

console.log(`rows ${rows.length}`);
